interface Link { href: string; method?: string; type?: string }
type Links = Record<string, Link>;

// Producer: embed relative hrefs; never internal hostnames
const order: { id: string; _links: Links } = { id: "42", _links: {
  payment: { href: "/payments/42", method: "GET" } } };

// Consumer: select by rel, resolve, dereference
const pay = order._links["payment"];
const url = new URL(pay.href, "https://api.example.com"); // validates + resolves relative refs
const res = await fetch(url);
if (!res.ok) throw new Error(`dead link: HTTP ${res.status}`); // fetch rejects on network errors only
const payment = await res.json();
